{
  "id": "lead-reminder-workflow",
  "name": "Lead Reminder After 24h",
  "nodes": [
    {
      "id": "11111111-1111-1111-1111-111111111111",
      "name": "Webhook - New Lead",
      "type": "n8n-nodes-base.webhook",
      "typeVersion": 1,
      "position": [200, 300],
      "parameters": {
        "httpMethod": "POST",
        "path": "lead/new",
        "responseMode": "onReceived",
        "responseData": {
          "options": {}
        }
      }
    },
    {
      "id": "22222222-2222-2222-2222-222222222222",
      "name": "Wait 24 Hours",
      "type": "n8n-nodes-base.wait",
      "typeVersion": 1,
      "position": [500, 300],
      "parameters": {
        "amount": 24,
        "unit": "hours"
      }
    },
    {
      "id": "33333333-3333-3333-3333-333333333333",
      "name": "Send Reminder Email",
      "type": "n8n-nodes-base.emailSend",
      "typeVersion": 1,
      "position": [800, 300],
      "parameters": {
        "fromEmail": "noreply@example.com",
        "toEmail": "={{ $json.email }}",
        "subject": "Erinnerung: Neuer Lead Follow-up",
        "text": "Hallo {{ $json.name }},\n\ndies ist eine automatische Erinnerung für den Lead, der vor 24 Stunden eingegangen ist.\n\nLead-Details:\n- Name: {{ $json.name }}\n- E-Mail: {{ $json.email }}\n- Firma: {{ $json.company || 'Nicht angegeben' }}\n- Nachricht: {{ $json.message || 'Keine Nachricht' }}\n\nBitte kümmern Sie sich um den Follow-up.\n\nMit freundlichen Grüßen\nIhr CRM-System"
      }
    }
  ],
  "connections": {
    "Webhook - New Lead": {
      "main": [[{"node": "Wait 24 Hours", "type": "main", "index": 0}]]
    },
    "Wait 24 Hours": {
      "main": [[{"node": "Send Reminder Email", "type": "main", "index": 0}]]
    }
  }
}

{
  "id": "google-sheets-to-slack-workflow",
  "name": "Google Sheets to Slack Notification",
  "nodes": [
    {
      "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
      "name": "Google Sheets Trigger",
      "type": "n8n-nodes-base.googleSheetsTrigger",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "operation": "onAdd",
        "spreadsheetId": "",
        "sheetName": "",
        "range": "A:Z",
        "pollTimes": {
          "item": [
            {
              "mode": "everyMinute"
            }
          ]
        }
      }
    },
    {
      "id": "b2c3d4e5-f6a7-8901-bcde-f23456789012",
      "name": "Format Slack Message",
      "type": "n8n-nodes-base.set",
      "typeVersion": 1,
      "position": [500, 300],
      "parameters": {
        "keepOnlySet": true,
        "values": {
          "string": [
            {
              "name": "message",
              "value": "📊 Neue Zeile in Google Sheets hinzugefügt!\n\n**Daten:**\n{{ JSON.stringify($json, null, 2) }}"
            }
          ]
        }
      }
    },
    {
      "id": "c3d4e5f6-a7b8-9012-cdef-345678901234",
      "name": "Send to Slack",
      "type": "n8n-nodes-base.slack",
      "typeVersion": 1,
      "position": [750, 300],
      "parameters": {
        "operation": "post",
        "channel": "#team-notifications",
        "text": "={{ $json.message }}",
        "options": {
          "username": "Google Sheets Bot",
          "iconEmoji": ":bar_chart:"
        }
      }
    }
  ],
  "connections": {
    "Google Sheets Trigger": {
      "main": [
        [
          {
            "node": "Format Slack Message",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Format Slack Message": {
      "main": [
        [
          {
            "node": "Send to Slack",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  }
}

{
  "id": "weekly-monday-api-to-airtable",
