      "typeVersion": 1,
      "position": [750, 300],
      "parameters": {
        "fieldToSplitOut": "data",
        "options": {}
      }
    },
    {
      "id": "d4e5f6a7-b8c9-0123-defg-456789012345",
      "name": "Create Airtable Record",
      "type": "n8n-nodes-base.airtable",
      "typeVersion": 1,
      "position": [1000, 300],
      "parameters": {
        "operation": "create",
        "baseId": "YOUR_BASE_ID",
        "tableId": "YOUR_TABLE_ID",
        "columns": {
          "mappingMode": "defineBelow",
          "value": {
            "Field1": "={{ $json.column1 }}",
            "Field2": "={{ $json.column2 }}",
            "Field3": "={{ $json.column3 }}"
          }
        }
      }
    }
  ],
  "connections": {
    "Manual Trigger": {
      "main": [
        [
          {
            "node": "Read CSV File",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Read CSV File": {
      "main": [
        [
          {
            "node": "Split CSV Rows",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Split CSV Rows": {
      "main": [
        [
          {
            "node": "Create Airtable Record",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  }
}

