  "id": "daily-airtable-export-email",
  "name": "Daily Airtable Export to Email",
  "nodes": [
    {
      "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
      "name": "Daily Midnight Trigger",
      "type": "n8n-nodes-base.scheduleTrigger",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "triggerTimes": {
          "item": [
            {
              "mode": "everyDay",
              "hour": 0,
              "minute": 0
            }
          ]
        }
      }
    },
    {
      "id": "b2c3d4e5-f6a7-8901-bcde-f23456789012",
      "name": "Get Airtable Records",
      "type": "n8n-nodes-base.airtable",
      "typeVersion": 1,
      "position": [500, 300],
      "parameters": {
        "operation": "getAll",
        "baseId": "YOUR_BASE_ID",
        "tableId": "YOUR_TABLE_ID",
        "options": {}
      }
    },
    {
      "id": "c3d4e5f6-a7b8-9012-cdef-345678901234",
      "name": "Prepare CSV Attachment",
      "type": "n8n-nodes-base.code",
      "typeVersion": 1,
      "position": [750, 300],
      "parameters": {
        "mode": "runOnceForAllItems",
        "jsCode": "const records = items.map(item => item.json);\nif (records.length === 0) return [{ json: {}, binary: {} }];\n\nconst headers = Object.keys(records[0].fields || records[0]);\nconst rows = records.map(r => {\n  const fields = r.fields || r;\n  return headers.map(h => fields[h] ?? '').map(v => `\"${String(v).replace(/\\\"/g, '\"\"')}\"`).join(',');\n});\nconst csv = [headers.join(','), ...rows].join('\\n');\n\nreturn [{\n  json: {},\n  binary: {\n    attachment: {\n      data: Buffer.from(csv).toString('base64'),\n      mimeType: 'text/csv',\n      fileName: `airtable-export-${new Date().toISOString().split('T')[0]}.csv`\n    }\n  }\n}];"
      }
    },
    {
      "id": "d4e5f6a7-b8c9-0123-def0-456789012345",
      "name": "Send Email with Attachment",
      "type": "n8n-nodes-base.emailSend",
      "typeVersion": 1,
      "position": [1000, 300],
      "parameters": {
        "fromEmail": "noreply@yourdomain.com",
        "toEmail": "recipient@example.com",
        "subject": "Daily Airtable Export - {{ $now.format('YYYY-MM-DD') }}",
        "text": "Please find attached the daily Airtable export for {{ $now.format('YYYY-MM-DD') }}.",
        "options": {
          "attachments": [
            {
              "binaryPropertyName": "attachment"
            }
          ]
        }
      }
    }
  ],
  "connections": {
    "Daily Midnight Trigger": {
      "main": [
        [
          {
            "node": "Get Airtable Records",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Get Airtable Records": {
      "main": [
        [
          {
            "node": "Prepare CSV Attachment",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Prepare CSV Attachment": {
      "main": [
        [
          {
            "node": "Send Email with Attachment",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  }
}

