{
  "id": "status-monitor-workflow",
  "name": "API Status Monitor",
  "nodes": [
    {
      "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
      "name": "Schedule Trigger",
      "type": "n8n-nodes-base.scheduleTrigger",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "rule": {
          "interval": 15,
          "unit": "minutes"
        }
      }
    },
    {
      "id": "b2c3d4e5-f6a7-8901-bcde-f23456789012",
      "name": "HTTP Request",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 1,
      "position": [500, 300],
      "parameters": {
        "method": "GET",
        "url": "https://api.example.com/status",
        "options": {
          "timeout": 10000
        }
      }
    },
    {
      "id": "c3d4e5f6-a7b8-9012-cdef-345678901234",
      "name": "Check Status Change",
      "type": "n8n-nodes-base.code",
      "typeVersion": 1,
      "position": [750, 300],
      "parameters": {
        "mode": "runOnceForAllItems",
        "jsCode": "const previousStatus = $getWorkflowStaticData('global').lastStatus;\nconst currentStatus = $json.status;\n\nconst hasChanged = previousStatus !== undefined && previousStatus !== currentStatus;\n\n$setWorkflowStaticData('global', { lastStatus: currentStatus });\n\nreturn [{ json: { hasChanged, currentStatus, previousStatus } }];"
      }
    },
    {
      "id": "d4e5f6a7-b8c9-0123-defg-456789012345",
      "name": "If Status Changed",
      "type": "n8n-nodes-base.if",
      "typeVersion": 1,
      "position": [1000, 300],
      "parameters": {
        "conditions": {
          "boolean": [
            {
              "value1": "{{ $json.hasChanged }}",
              "operation": "true"
            }
          ]
        }
      }
    },
    {
      "id": "e5f6a7b8-c9d0-1234-efgh-567890123456",
      "name": "Send Slack Notification",
      "type": "n8n-nodes-base.slack",
      "typeVersion": 1,
      "position": [1250, 200],
      "parameters": {
        "operation": "post",
        "channel": "#alerts",
        "text": "Status changed from *{{ $json.previousStatus }}* to *{{ $json.currentStatus }}*",
        "options": {
          "username": "Status Monitor",
          "iconEmoji": ":warning:"
        }
      }
    },
    {
      "id": "f6a7b8c9-d0e1-2345-fghi-678901234567",
      "name": "No Change",
      "type": "n8n-nodes-base.noOp",
      "typeVersion": 1,
      "position": [1250, 400],
      "parameters": {}
    }
  ],
  "connections": {
    "Schedule Trigger": {
      "main": [[{ "node": "HTTP Request", "type": "main", "index": 0 }]]
    },
    "HTTP Request": {
      "main": [[{ "node": "Check Status Change", "type": "main", "index": 0 }]]
    },
    "Check Status Change": {
      "main": [[{ "node": "If Status Changed", "type": "main", "index": 0 }]]
    },
    "If Status Changed": {
      "main": [
        [{ "node": "Send Slack Notification", "type": "main", "index": 0 }],
        [{ "node": "No Change", "type": "main", "index": 0 }]
      ]
    }
  }
}

