{
  "id": "csv-airtable-importer",
  "name": "CSV zu Airtable",
  "nodes": [
    {
      "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
      "name": "Manueller Trigger",
      "type": "n8n-nodes-base.manualTrigger",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {}
    },
    {
      "id": "b2c3d4e5-f6a7-8901-bcde-f23456789012",
      "name": "CSV Datei lesen",
      "type": "n8n-nodes-base.readWriteFile",
      "typeVersion": 1,
      "position": [250, 100],
      "parameters": {
        "fileName": "/pfad/zur/deiner_datei.csv",
        "options": {}
      }
    },
    {
      "id": "c3d4e5f6-a7b8-9012-cdef-345678901234",
      "name": "CSV parsen und splitten",
      "type": "n8n-nodes-base.code",
      "typeVersion": 1,
      "position": [480, 100],
      "parameters": {
        "JSCode": "const binaryData = items[0].binary?.data;\nif (!binaryData || !binaryData.data) {\n  return items;\n}\n\nconst text = Buffer.from(binaryData.data).toString('utf-8');\nconst lines = text.trim().split('\\n');\nif (lines.length < 2) {\n  return [];\n}\n\nconst headers = lines[0].split(',').map(h => h.trim().replace(/^\"(.+)\"$/, '$1'));\n\nconst result = [];\nfor (let i = 1; i < lines.length; i++) {\n  const values = lines[i].match(/\\\"([^\\\"]+)\\\"|([^,]+)/g) || [];\n  const record = {};\n  headers.forEach((h, idx) => {\n    const raw = values[idx] || '';\n    record[h] = raw.replace(/^\"(.+)\"$/, '$1').trim();\n  });\n  result.push({ json: record });\n}\nreturn result;"
      }
    },
    {
      "id": "d4e5f6a7-b8c9-0123-def0-456789012345",
      "name": "Airtable Datensätze erstellen",
      "type": "n8n-nodes-base.airtable",
      "typeVersion": 1,
      "position": [710, 100],
      "parameters": {
        "operation": "append",
        "applicationId": "={{ $env.airtable_base_id }}",
        "tableId": "={{ $env.airtable_table_id }}",
        "fields": {}
      }
    }
  ],
  "connections": {
    "Manueller Trigger": {
      "main": [[{"node": "CSV Datei lesen", "type": "main", "index": 0}]]
    },
    "CSV Datei lesen": {
      "main": [[{"node": "CSV parsen und splitten", "type": "main", "index": 0}]]
    },
    "CSV parsen und splitten": {
      "main": [[{"node": "Airtable Datensätze erstellen", "type": "main", "index": 0}]]
    }
  }
}

