{
  "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
  "name": "Google Calendar Erinnerungsmail",
  "nodes": [
    {
      "id": "11111111-1111-1111-1111-111111111111",
      "name": "Neuer Kalendereintrag",
      "type": "n8n-nodes-base.googleCalendarTrigger",
      "typeVersion": 1,
      "position": [200, 300],
      "parameters": {
        "event": "add",
        "calendar": "primary"
      }
    },
    {
      "id": "22222222-2222-2222-2222-222222222222",
      "name": "Erinnerungszeit berechnen",
      "type": "n8n-nodes-base.code",
      "typeVersion": 1,
      "position": [400, 300],
      "parameters": {
        "jsCode": "const eventStart = new Date(items[0].json.start);\nconst reminderTime = new Date(eventStart.getTime() - 24 * 60 * 60 * 1000);\nconst now = new Date();\nconst delayMs = reminderTime.getTime() - now.getTime();\n\nreturn {\n  json: {\n    reminderTime: reminderTime.toISOString(),\n    delayMs: Math.max(0, delayMs),\n    eventTitle: items[0].json.summary,\n    eventStart: items[0].json.start\n  }\n};"
      }
    },
    {
      "id": "33333333-3333-3333-3333-333333333333",
      "name": "Warten bis Erinnerungszeit",
      "type": "n8n-nodes-base.wait",
      "typeVersion": 1,
      "position": [600, 300],
      "parameters": {
        "amount": 0,
        "unit": "seconds",
        "until": "={{ $json.reminderTime }}",
        "options": {}
      }
    },
    {
      "id": "44444444-4444-4444-4444-444444444444",
      "name": "Erinnerungsmail senden",
      "type": "n8n-nodes-base.emailSend",
      "typeVersion": 1,
      "position": [800, 300],
      "parameters": {
        "from": "n8n@beispiel.de",
        "to": "empfaenger@beispiel.de",
        "subject": "Erinnerung: ={{ $json.eventTitle }}",
        "text": "Dies ist eine Erinnerung für deinen Kalendereintrag: ={{ $json.eventTitle }} am ={{ $json.eventStart }}"
      }
    }
  ],
  "connections": {
    "Neuer Kalendereintrag": {
      "main": [[{"node": "Erinnerungszeit berechnen", "type": "main", "index": 0}]]
    },
    "Erinnerungszeit berechnen": {
      "main": [[{"node": "Warten bis Erinnerungszeit", "type": "main", "index": 0}]]
    },
