      "name": "Write New Status",
      "type": "n8n-nodes-base.readWriteFile",
      "typeVersion": 1,
      "position": [1250, 500],
      "parameters": {
        "operation": "write",
        "filePath": "/tmp/last_status.json",
        "dataPropertyName": "status",
        "options": {}
      }
    }
  ],
  "connections": {
