      "type": "n8n-nodes-base.googleCalendarTrigger",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "eventTypes": ["created"],
        "calendarId": "primary",
        "pollTimes": {
          "item": [
            {
              "mode": "everyMinute"
            }
          ]
        }
      }
    },
    {
      "id": "22222222-2222-2222-2222-222222222222",
      "name": "Wait Until 1 Day Before",
      "type": "n8n-nodes-base.wait",
      "typeVersion": 1,
      "position": [500, 300],
      "parameters": {
        "waitUntil": "specificDateTime",
        "dateTime": "={{ $json.start.dateTime ? new Date(new Date($json.start.dateTime).getTime() - 24 * 60 * 60 * 1000).toISOString() : new Date(new Date($json.start.date).getTime() - 24 * 60 * 60 * 1000).toISOString() }}",
        "timezone": "={{ $json.start.timeZone || 'UTC' }}"
      }
    },
    {
      "id": "33333333-3333-3333-3333-333333333333",
      "name": "Send Reminder Email",
      "type": "n8n-nodes-base.emailSend",
      "typeVersion": 1,
      "position": [750, 300],
      "parameters": {
        "fromEmail": "reminder@example.com",
        "toEmail": "={{ $json.attendees?.map(a => a.email).join(',') || 'user@example.com' }}",
        "subject": "Erinnerung: {{ $json.summary }} morgen",
        "text": "Hallo,\n\ndas ist eine Erinnerung an dein morgiges Event:\n\n**{{ $json.summary }}**\n\nZeit: {{ $json.start.dateTime || $json.start.date }}\nOrt: {{ $json.location || 'Kein Ort angegeben' }}\n\nBeschreibung: {{ $json.description || 'Keine Beschreibung' }}\n\nViele Grüße\nDein Kalender-Assistent"
      }
    }
  ],
  "connections": {
    "Google Calendar Trigger": {
      "main": [
        [
          {
            "node": "Wait Until 1 Day Before",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Wait Until 1 Day Before": {
      "main": [
        [
          {
            "node": "Send Reminder Email",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  }
}

{
  "id": "poll-api-status-change",
  "name": "Poll API for Status Changes",
  "nodes": [
    {
      "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
      "name": "Every 15 Minutes",
      "type": "n8n-nodes-base.scheduleTrigger",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "triggerTimes": {
          "item": [
            {
              "mode": "everyX",
              "value": 15,
              "unit": "minutes"
            }
          ]
        }
      }
    },
    {
      "id": "b2c3d4e5-f6a7-8901-bcde-f23456789012",
      "name": "Call API",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 1,
      "position": [500, 300],
      "parameters": {
        "url": "https://api.example.com/status",
        "method": "GET",
        "responseFormat": "json",
        "jsonParameters": true,
        "options": {}
      }
    },
    {
      "id": "c3d4e5f6-a7b8-9012-cdef-345678901234",
      "name": "Read Previous Status",
      "type": "n8n-nodes-base.readWriteFile",
      "typeVersion": 1,
      "position": [500, 500],
      "parameters": {
        "operation": "read",
        "filePath": "/data/previous_status.json",
        "options": {}
      }
    },
    {
      "id": "d4e5f6a7-b8c9-0123-def0-456789012345",
      "name": "Compare Status",
      "type": "n8n-nodes-base.if",
      "typeVersion": 1,
      "position": [750, 300],
      "parameters": {
        "conditions": {
          "string": [
            {
              "value1": "={{ $json.status }}",
              "operation": "notEqual",
              "value2": "={{ $node[\"Read Previous Status\"].json[\"status\"] }}"
            }
          ]
        }
      }
    },
    {
      "id": "e5f6a7b8-c9d0-1234-ef01-567890123456",
      "name": "Send Slack Notification",
      "type": "n8n-nodes-base.slack",
      "typeVersion": 1,
      "position": [1000, 200],
      "parameters": {
        "resource": "message",
        "operation": "post",
        "channel": "#alerts",
        "text": "Status changed from *{{ $node[\"Read Previous Status\"].json[\"status\"] }}* to *{{ $json.status }}*",
        "options": {}
      }
    },
    {
      "id": "f6a7b8c9-d0e1-2345-f012-678901234567",
      "name": "Save Current Status",
      "type": "n8n-nodes-base.readWriteFile",
      "typeVersion": 1,
      "position": [1000, 400],
      "parameters": {
        "operation": "write",
        "filePath": "/data/previous_status.json",
        "data": "={{ JSON.stringify({ status: $json.status, timestamp: new Date().toISOString() }) }}",
        "options": {}
      }
    },
    {
      "id": "a7b8c9d0-e1f2-3456-0123-789012345678",
      "name": "Save Current Status (No Change)",
      "type": "n8n-nodes-base.readWriteFile",
      "typeVersion": 1,
      "position": [1000, 500],
      "parameters": {
        "operation": "write",
        "filePath": "/data/previous_status.json",
        "data": "={{ JSON.stringify({ status: $json.status, timestamp: new Date().toISOString() }) }}",
        "options": {}
      }
    }
  ],
  "connections": {
    "Every 15 Minutes": {
      "main": [[{"node": "Call API", "type": "main", "index": 0}]]
    },
    "Call API": {
      "main": [
        [{"node": "Read Previous Status", "type": "main", "index": 0}],
        [{"node": "Compare Status", "type": "main", "index": 0}]
      ]
    },
    "Read Previous Status": {
      "main": [[{"node": "Compare Status", "type": "main", "index": 0}]]
    },
    "Compare Status": {
      "main": [
        [{"node": "Send Slack Notification", "type": "main", "index": 0}],
        [{"node": "Save Current Status (No Change)", "type": "main", "index": 0}]
      ]
    },
    "Send Slack Notification": {
      "main": [[{"node": "Save Current Status", "type": "main", "index": 0}]]
    }
  }
}

